@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + practitionerNumber : int
}

class HeadDoctor {
  + name : string
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
}

class ConsentForm {
  + signature : string
  + dateSigned : date
  + dateRetracted : date
}

class Illness {
  + name : string
  + priorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

class TreatmentStage {
  + level : int
}

class TreatmentRecord {
  + currentStage : int
  + lastUpdated : datetime
}

HospitalHouseMD "1" o-- "1..*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "1..*" Diagnosis
Diagnosis "1" -- "1" Illness
HospitalHouseMD "1" *-- "1..*" Treatment
Treatment "1" -- "0..*" Diagnosis
Diagnosis "1" -- "0..*" TreatmentRecord
Patient "1" -- "0..*" TreatmentRecord
TreatmentRecord "1" -- "1" Treatment
TreatmentRecord "1" -- "1" TreatmentStage
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "1..*" TreatmentRecord
Doctor "1" -- "0..*" TreatmentRecord
HeadDoctor --|> Doctor
HeadDoctor "1" -- "0..*" Diagnosis : approves

@enduml

